"""Bounded, sequential laptop pilot. Run in its isolated benchmark snapshot."""
from pathlib import Path
import hashlib,json,math,os,statistics,subprocess,time
from tools.sloppy_core import benchmark_compile as bc, benchmark_apps as ba
from tools.sloppy_core.benchmark_sloppy import generate_dewy
from tools.sloppy_core.performance_gate import compare_samples,save_report,toolchain_identity
root=Path.cwd();out=root/'results';out.mkdir(exist_ok=True)
os.sched_setaffinity(0,{1})
cs={label:root/'bundles'/name/'bin/dewy-core' for label,name in [('control','build-1792436050115052261'),('candidate','build-1792439908092933901')]}
ids={k:toolchain_identity(c) for k,c in cs.items()}
def machine():
 def read(p):
  try:return Path(p).read_text().strip()
  except OSError:return None
 return {'time':time.time(),'load':os.getloadavg(),'cpuinfo':read('/proc/cpuinfo'),'meminfo':read('/proc/meminfo'),
 'power':{str(p):read(p) for p in Path('/sys/class/power_supply').glob('*/online')},
 'temperatures':{str(p):read(p) for p in Path('/sys/class/thermal').glob('thermal_zone*/temp')},
 'governors':{str(p):read(p) for p in Path('/sys/devices/system/cpu').glob('cpu[0-9]*/cpufreq/scaling_governor')}}
report={'status':'incomplete','scope':'Light laptop pilot, not the complete fixed-reference acceptance gate. Normal power policy, single CPU and emitter, warm file caches, fresh compiler process/output each sample.', 'origin':json.loads((root/'ORIGIN.json').read_text()),'toolchains':ids,'machine_start':machine()}
source=root/'__dewycache__/throughput.dewy';source.parent.mkdir(exist_ok=True);source.write_text(generate_dewy(2000));lines=len(source.read_text().splitlines());report['root_source_lines']=lines
bc.WORKLOADS.update({'throughput-default':('build',str(source)),'throughput-release':('build',str(source),'--release'),'compiler-reference':('build',str(root/'reference-compiler/main.jo'))})
def validate(name,label,binary):
 if not name.startswith('throughput-'):return False
 run=subprocess.run([binary],capture_output=True,text=True,check=True,timeout=30)
 assert math.isclose(float(run.stdout.strip()),102380577.8970889,rel_tol=1e-12)
 return True
def save():save_report(out/'laptop-pilot.json',report)
def progress(r):report['compilation']=r;save()
save()
report['compilation']=bc.measure(cs,['throughput-default','throughput-release','tour-default','netpong-default','dunes-default','netpong-web-default','compiler-reference'],7,1,validate,on_progress=progress)
report['compile_comparisons']={n:compare_samples(w['cpu_seconds']['control'],w['cpu_seconds']['candidate']) for n,w in report['compilation']['workloads'].items()}
report['throughput_lines_per_second']={n:{label:{'wall':lines/w['median_seconds'][label],'cpu':lines/w['median_cpu_seconds'][label]} for label in cs} for n,w in report['compilation']['workloads'].items() if n.startswith('throughput-')};save()
# Keep this first laptop visit small: four representative runtime kernels, with
# all existing boundary checks and both Dewy modes, using the normal C -O2 baseline.
report['runtime']=ba.measure(cs,['records','text','managed_params','branch_dispatch'],7,'gcc',clock='thread-cpu',mode='both')
report['runtime_comparisons']={}
for name,w in report['runtime']['workloads'].items():
 assert w['preflight_checksums']['1000']==ba.CHECKSUMS_1000[name]
 t={label:[row['kernel_ns'] for row in rows] for label,rows in w['samples'].items()}
 report['runtime_comparisons'][name]={mode:{'previous':compare_samples(t['control-'+mode],t['candidate-'+mode]),'c':compare_samples(t['c'],t['candidate-'+mode],limit=1.0),'median_ratio_to_c':statistics.median(t['candidate-'+mode])/statistics.median(t['c'])} for mode in ['default','release']}
assert ids=={k:toolchain_identity(c) for k,c in cs.items()}
report['machine_end']=machine();report['status']='complete';save()
print(json.dumps({'compilation':report['compile_comparisons'],'throughput':report['throughput_lines_per_second'],'runtime':report['runtime_comparisons']},indent=2),flush=True)

reproduction.diagnostic_source:
from pathlib import Path
import json,os,math,resource,statistics,subprocess,time
from tools.sloppy_core.benchmark_compile import sample_order
from tools.sloppy_core.performance_gate import toolchain_identity,compare_samples,save_report
r=Path.cwd();o=r/'results';os.sched_setaffinity(0,{1})
cs={k:r/'bundles'/v/'bin/dewy-core' for k,v in [('old-host','build-1792436050115052261'),('new-host','build-1792439908092933901'),('old-native','build-1792435417951261960'),('new-native','build-1792439437291931994')]}
ids={k:toolchain_identity(v) for k,v in cs.items()};env={k:v for k,v in os.environ.items() if not k.startswith(('DEWY_','SLOPPY_'))};env['SLOPPY_EMIT_WORKERS']='1'
report={'status':'incomplete','reason':'Diagnose release-build regression in first laptop pilot; compare source changes in native and optimized-host builds, and count instructions. Follow-up is not a replacement for the original pilot.','toolchains':ids,'instructions':{},'samples':{},'load_start':os.getloadavg()}
args=['build',str(r/'__dewycache__/throughput.dewy'),'--release','--time','-o',str(o/'diagnostic-output')]
for k,c in cs.items():
 rows=[]
 for _ in range(3):
  run=subprocess.run([o/'count-instructions',c,*args],env=env,capture_output=True,text=True,timeout=30)
  if run.returncode:
   report['counter_unavailable']=run.stderr;break
  row=json.loads(run.stderr.splitlines()[-1]);assert row['enabled_ns']==row['running_ns'];rows.append(row)
 report['instructions'][k]=rows
 save_report(o/'laptop-diagnostic.json',report)
 if 'counter_unavailable' in report:break
labels=list(cs);report['samples']={k:[] for k in labels}
for sample in range(8):
 for k in sample_order(labels,sample):
  before=resource.getrusage(resource.RUSAGE_CHILDREN);start=time.perf_counter()
  run=subprocess.run([cs[k],*args],env=env,capture_output=True,text=True,timeout=30,check=True)
  wall=time.perf_counter()-start;after=resource.getrusage(resource.RUSAGE_CHILDREN)
  if sample:report['samples'][k].append({'wall_seconds':wall,'cpu_seconds':after.ru_utime+after.ru_stime-before.ru_utime-before.ru_stime,'phases':run.stderr})
  if sample==7:
   result=subprocess.run([o/'diagnostic-output'],capture_output=True,text=True,check=True,timeout=30)
   assert math.isclose(float(result.stdout.strip()),102380577.8970889,rel_tol=1e-12)
report['comparisons']={kind:compare_samples([x['cpu_seconds'] for x in report['samples']['old-'+kind]],[x['cpu_seconds'] for x in report['samples']['new-'+kind]]) for kind in ['host','native']}
assert ids=={k:toolchain_identity(v) for k,v in cs.items()};report['status']='complete';report['load_end']=os.getloadavg();save_report(o/'laptop-diagnostic.json',report)
print(json.dumps({'instructions':{k:statistics.median(x['instructions'] for x in rows) for k,rows in report['instructions'].items() if rows},'comparisons':report['comparisons']},indent=2),flush=True)

